// Applied rules: [C3.S2, III③]
// Skipped rules: [III④: Only one concrete cursor-index-deref hit [11], and it is a single trailing NUL write rather than a multi-access cursor walk. Per rule guidance, a slice view serving a single access should be skipped. The memmove site is better handled by III③ with raw-pointer `ptr::copy`.; C3.S1: Would require changing the `pub unsafe fn` raw-pointer signature and auditing all callers for aliasing/non-null/length guarantees; the local reload issue is adequately handled by C3.S2.; II_inl: The uninlined callees are `xmlBufMemoryError` and `xmlBufResize`. `xmlBufMemoryError` appears on cold error paths, so inlining is unlikely to pay and may bloat code. `xmlBufResize` is nontrivial and marked TooCostly; forcing inline is risky and not justified before local rewrites.]
#[inline]
pub unsafe fn xmlBufAdd(
    mut buf: xmlBufPtr,
    mut str: *const xmlChar,
    mut len: c_int,
) -> c_int {
    let mut needSize: size_t = 0;
    if str.is_null() || buf.is_null() || (*buf).error != 0 {
        return -(1 as c_int);
    }
    if (*buf).size != (*buf).compat_size as size_t {
        if (*buf).compat_size < INT_MAX as c_uint {
            (*buf).size = (*buf).compat_size as size_t;
        }
    }
    if (*buf).use_0 != (*buf).compat_use as size_t {
        if (*buf).compat_use < INT_MAX as c_uint {
            (*buf).use_0 = (*buf).compat_use as size_t;
        }
    }
    if len < -(1 as c_int) {
        return -(1 as c_int);
    }
    if len == 0 as c_int {
        return 0 as c_int;
    }
    if len < 0 as c_int {
        len = xmlStrlen(str);
    }
    if len < 0 as c_int {
        return -(1 as c_int);
    }
    if len == 0 as c_int {
        return 0 as c_int;
    }
    if len as size_t >= (*buf).size.wrapping_sub((*buf).use_0) {
        if len as size_t >= SIZE_MAX.wrapping_sub((*buf).use_0) {
            xmlBufMemoryError(
                buf,
                b"growing buffer past SIZE_MAX\0" as *const u8 as *const c_char,
            );
            return -(1 as c_int);
        }
        needSize = (*buf)
            .use_0
            .wrapping_add(len as size_t)
            .wrapping_add(1 as size_t);
        if (*buf).alloc as c_uint == XML_BUFFER_ALLOC_BOUNDED as c_int as c_uint {
            if needSize >= XML_MAX_TEXT_LENGTH as size_t {
                xmlBufMemoryError(
                    buf,
                    b"buffer error: text too long\n\0" as *const u8 as *const c_char,
                );
                return -(1 as c_int);
            }
        }
        if xmlBufResize(buf, needSize) == 0 {
            xmlBufMemoryError(buf, b"growing buffer\0" as *const u8 as *const c_char);
            return XML_ERR_NO_MEMORY as c_int;
        }
    }
    let content = (*buf).content;
    let use_0 = (*buf).use_0;
    // SAFETY: `buf` is valid and, after the resize logic above, `content.add(use_0)`
    // has space for `len` xmlChar elements plus the trailing NUL; `ptr::copy`
    // preserves memmove overlap semantics for potentially overlapping regions.
    unsafe {
        core::ptr::copy(str, content.add(use_0), len as usize);
    }
    let new_use = use_0.wrapping_add(len as size_t);
    (*buf).use_0 = new_use;
    // SAFETY: same capacity proof as above; the trailing NUL is written at the
    // first byte after the copied `len` elements within the buffer allocation.
    unsafe {
        *content.add(new_use) = 0 as xmlChar;
    }
    let size = (*buf).size;
    if size < INT_MAX as size_t {
        (*buf).compat_size = size as c_uint;
    } else {
        (*buf).compat_size = INT_MAX as c_uint;
    }
    if new_use < INT_MAX as size_t {
        (*buf).compat_use = new_use as c_uint;
    } else {
        (*buf).compat_use = INT_MAX as c_uint;
    }
    return 0 as c_int;
}

